// Parse Gemini JSON output and fan out one item per image prompt
const text = $json.content.parts[0].text;

let clean = text.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/, '')
  .replace(/```$/, '')
  .trim();

let data;
try { data = JSON.parse(clean); } catch (e) { throw new Error('Model did not return valid JSON. Raw: ' + clean); }

const caption = (data.caption || '').trim();
const prompts = Array.isArray(data.image_prompts) ? data.image_prompts : [];
if (!caption) throw new Error('No caption returned by the model.');
if (prompts.length === 0) throw new Error('No image_prompts returned. Raw: ' + clean);

return prompts.map((p, idx) => ({ json: { image_prompt: String(p).trim(), caption, index: idx + 1, total: prompts.length } }));

// Drop corrupted/empty images (Gemini sometimes returns a 0-byte image)
const all = $input.all();
const out = [];
let bad = 0;
for (let i = 0; i < all.length; i++) {
  const meta = all[i].binary && all[i].binary.data;
  let size = 0;
  if (meta) {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    size = buf ? buf.length : 0;
  }
  if (size > 1024) { out.push(all[i]); } else { bad++; }
}
if (out.length < 2) {
  throw new Error('Only ' + out.length + ' valid image(s) generated (need >=2 for a Facebook album); ' + bad + ' were corrupted/empty. Please re-run.');
}
return out;

// Aggregate all photo ids (for the album) + urls (for reference)
const media = items.map(i => ({ media_fbid: i.json.id }));
if (media.length === 0) throw new Error('No photos were uploaded.');
if (media.some(m => !m.media_fbid)) throw new Error('A photo upload returned no id: ' + JSON.stringify(items.map(i => i.json)));

const urls = items.map(i => (i.json.images && i.json.images[0] ? i.json.images[0].source : null)).filter(Boolean);
const caption = $('Parse & Split Prompts').first().json.caption;

return [{ json: { attached_media: JSON.stringify(media), photo_count: media.length, caption, urls } }];

const postId = $json.id || $json.post_id || 'unknown';
const count = $('Collect Photo IDs').first().json.photo_count;
const caption = $('Parse & Split Prompts').first().json.caption;
const text = ['\u2705 *Facebook album PUBLISHED*', `*Post ID:* ${postId}`, `*Images:* ${count}`, `*Caption:* ${caption}`].join('\n');
return [{ json: { text, postId, count } }];

